BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT plan(14);
INSERT INTO auth.users(id,email) VALUES('eeeeeeee-0000-0000-0000-000000000001','embeddinga@test.local'),('eeeeeeee-0000-0000-0000-000000000002','embeddingb@test.local');
INSERT INTO public.works(id,user_id,work_type,title) VALUES('eeeeeeee-1000-0000-0000-000000000001','eeeeeeee-0000-0000-0000-000000000001','book','Thermodynamics'),('eeeeeeee-1000-0000-0000-000000000002','eeeeeeee-0000-0000-0000-000000000002','book','Private second owner');
INSERT INTO public.records(id,work_id,record_type) VALUES('eeeeeeee-2000-0000-0000-000000000001','eeeeeeee-1000-0000-0000-000000000001','edition'),('eeeeeeee-2000-0000-0000-000000000002','eeeeeeee-1000-0000-0000-000000000002','edition');
INSERT INTO public.assets(id,user_id,bucket,storage_path,file_size,checksum_sha256,mime_type,file_format,metadata) SELECT ('eeeeeeee-3000-0000-0000-00000000000'||n)::uuid,('eeeeeeee-0000-0000-0000-00000000000'||n)::uuid,'documents','embedding-fixture-'||n||'.pdf',100,'embedding-'||n,'application/pdf','pdf','{"passage_index":{"version":"v1","status":"complete"}}' FROM generate_series(1,2) n;
INSERT INTO public.record_assets(record_id,asset_id) SELECT ('eeeeeeee-2000-0000-0000-00000000000'||n)::uuid,('eeeeeeee-3000-0000-0000-00000000000'||n)::uuid FROM generate_series(1,2) n;
INSERT INTO public.asset_passages(asset_id,user_id,index_version,ordinal,page,content,embedding,embedding_digest) SELECT 'eeeeeeee-3000-0000-0000-000000000001','eeeeeeee-0000-0000-0000-000000000001','v1',n,9,CASE WHEN n=1 THEN 'Entropy of an isolated system cannot decrease. güneş' ELSE 'Unrelated fixture '||n END,array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,repeat('a',64) FROM generate_series(1,10000) n;
INSERT INTO public.asset_passages(asset_id,user_id,index_version,ordinal,content) VALUES('eeeeeeee-3000-0000-0000-000000000001','eeeeeeee-0000-0000-0000-000000000001','v1',10001,'Last pending passage'),('eeeeeeee-3000-0000-0000-000000000002','eeeeeeee-0000-0000-0000-000000000002','v1',1,'Private entropy');
SELECT public.queue_embedding_jobs(repeat('a',64));
CREATE TEMP TABLE embedding_job AS SELECT id FROM public.jobs WHERE user_id='eeeeeeee-0000-0000-0000-000000000001' AND job_type='embed_passages';
UPDATE public.jobs SET status='running',claim_generation=7,lease_expires_at=now()+interval '1 minute' WHERE id=(SELECT id FROM embedding_job);
SELECT is(public.commit_embedding_batch((SELECT id FROM embedding_job),6,'[]'),false,'stale embedding claim cannot commit');
SELECT throws_ok($$SELECT public.commit_embedding_batch((SELECT id FROM embedding_job),7,jsonb_build_array(jsonb_build_object('id',(SELECT id FROM public.asset_passages WHERE user_id='eeeeeeee-0000-0000-0000-000000000002'),'embedding','[1]')))$$,NULL,NULL,'foreign passage rejected before embedding mutation');
SELECT is(public.commit_embedding_batch((SELECT id FROM embedding_job),7,jsonb_build_array(jsonb_build_object('id',(SELECT id FROM public.asset_passages WHERE ordinal=10001 AND user_id='eeeeeeee-0000-0000-0000-000000000001'),'embedding',array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector::text))),true,'owned vectors and job completion commit together');
SELECT is((SELECT status FROM public.jobs WHERE id=(SELECT id FROM embedding_job)),'succeeded','last embedding batch finishes job');
SET LOCAL ROLE authenticated;
SET LOCAL request.jwt.claims='{"sub":"eeeeeeee-0000-0000-0000-000000000001","role":"authenticated"}';
SELECT is((SELECT page FROM public.hybrid_passages('Entropy',array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,repeat('a',64),1)),9,'RRF ranks lexical evidence above semantic ties after page eight');
SELECT is((SELECT count(*)::int FROM public.hybrid_passages('güneş',NULL,repeat('a',64))),1,'non-English lexical retrieval survives missing vectors');
SELECT is_empty($$SELECT id FROM public.hybrid_passages('entropy',array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,repeat('a',64),20,ARRAY['eeeeeeee-1000-0000-0000-000000000002'::uuid])$$,'work filter runs before exact vector ranking');
SELECT is_empty($$SELECT id FROM public.hybrid_passages('absent',array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,repeat('b',64))$$,'digest mismatch cannot mix semantic spaces');
SELECT throws_ok($$SELECT public.queue_embedding_jobs(repeat('a',64))$$,'42501',NULL,'agent/owner cannot invoke service embedding scheduler');
SELECT throws_ok($$UPDATE public.asset_passages SET embedding=NULL$$,'42501',NULL,'owner cannot overwrite derived vectors');
SELECT results_eq($$SELECT id FROM public.hybrid_passages('unfindable',array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,repeat('a',64),20)$$,$$SELECT id FROM public.asset_passages WHERE user_id=auth.uid() AND embedding_digest=repeat('a',64) ORDER BY embedding OPERATOR(extensions.<=>) array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,id LIMIT 20$$,'semantic top twenty exactly matches owner-filtered reference');
SELECT is((public.passage_embedding_coverage(repeat('a',64))->>'embeddedPassages')::int,10001,'coverage counts current-digest owned passages');
SET LOCAL request.jwt.claims='{"sub":"eeeeeeee-0000-0000-0000-000000000002","role":"authenticated"}';
SELECT is((SELECT count(*)::int FROM public.hybrid_passages('entropy',array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,repeat('a',64))),1,'second owner sees only own lexical passage');
SELECT is((SELECT count(*)::int FROM public.asset_passages),1,'second owner cannot read first owner vectors');
SET LOCAL request.jwt.claims='{"sub":"eeeeeeee-0000-0000-0000-000000000001","role":"authenticated"}';
EXPLAIN (ANALYZE,BUFFERS) SELECT id FROM public.hybrid_passages('Entropy',array_prepend(1::real,array_fill(0::real,ARRAY[767]))::extensions.vector,repeat('a',64),20);
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
